import { cp, readFile, rm, writeFile } from 'node:fs/promises'

// Only remove files generated by the previous Pages build.
const manifest = '.pages-files.json'
let previous = []
try { previous = JSON.parse(await readFile(manifest, 'utf8')) } catch (error) {
  if (error.code !== 'ENOENT') throw error
}
for (const path of previous) {
  if (path === 'assets' || path === 'favicon.svg' || path === 'index.html' || path === '404.html' || path === '.nojekyll') {
    await rm(path, { recursive: true, force: true })
  }
}
await cp('dist/assets', 'assets', { recursive: true })
await cp('dist/index.html', 'index.html')
await cp('dist/index.html', '404.html')
await cp('dist/favicon.svg', 'favicon.svg')
await writeFile('.nojekyll', '')
await writeFile(manifest, JSON.stringify(['assets', 'index.html', '404.html', 'favicon.svg', '.nojekyll'], null, 2) + '\n')
console.log('Pages files ready in main / root. Commit these files and push to publish.')
